/** Called by the worker when an offer's deadline passes. */
export async function expireOffer(entryId: string): Promise<void> {
  await db.transaction(async (tx) => {
    const [entry] = await tx
      .update(s.waitlistEntries)
      .set({ status: "expired", offerToken: null, offerExpiresAt: null })
      .where(and(eq(s.waitlistEntries.id, entryId), eq(s.waitlistEntries.status, "offered")))
      .returning();
    if (!entry) return; // accepted or declined already

    await releaseOfferHold(entry);
    await queueNextOffer(tx, entry);
  });
}

/**
 * Passes an offer's slot on. Runs inside the transaction that ends the offer,
 * so the next offer is queued only if this one really ended.
 */
async function queueNextOffer(tx: Tx, entry: OfferRow): Promise<void> {
  const startMs = entry.offerSlotStartAt!.getTime();
  await enqueue(tx, {
    businessId: entry.businessId,
    topic: "waitlist.slot_freed",
    payload: {
      staffId: entry.offerStaffId!,
      serviceId: entry.serviceId,
      startMs,
      endMs: entry.offerSlotEndAt!.getTime(),
    },
    dedupeKey: `waitlist.refree:${entry.id}:${startMs}`,
  });
}

/**
 * Released before the transaction commits: the worker must never see the freed
 * slot while our hold still blocks it.
 */
async function releaseOfferHold(entry: OfferRow): Promise<void> {
  await releaseHold(entry.offerStaffId!, entry.offerSlotStartAt!.getTime());
}

async function releaseHold(staffId: string, startMs: number): Promise<void> {
  await redis().del(`hold:${staffId}:${startMs}`);
}

/**
 * The client turns the offer down. The slot goes to the next person in line,
 * or back to public stock if nobody is waiting. Only an outstanding offer can
 * be declined: a repeat tap, a second tab, or a claimed offer changes nothing.
 */
export async function declineOffer(token: string): Promise<void> {
  await db.transaction(async (tx) => {
    const [entry] = await tx
      .update(s.waitlistEntries)
      .set({ status: "declined", offerHoldToken: null })
      .where(and(eq(s.waitlistEntries.offerToken, token), eq(s.waitlistEntries.status, "offered")))
      .returning();
    if (!entry) return;

    await releaseOfferHold(entry);
    await queueNextOffer(tx, entry);
  });
}

