describe("declining an offer", () => {
  it("passes the slot to the next client and kills the link", async () => {
    const booked = await book();
    await join("+77012222222");
    await join("+77013333333");
    await cancel((booked as { bookingId: string }).bookingId);
    await drainOnce();
    await drainOnce();

    const first = (await entries()).find((r) => r.status === "offered")!;
    await declineOffer(first.offerToken!);
    await drainOnce(); // slot_freed -> offer to the second client
    await drainOnce(); // deliver it

    const rows = await entries();
    expect(rows.find((r) => r.id === first.id)!.status).toBe("declined");

    const second = rows.find((r) => r.status === "offered")!;
    const [client] = await db
      .select()
      .from(s.clients)
      .where(eq(s.clients.id, second.clientId));
