    await join("+77012222222");
    await join("+77013333333");
    await cancel((booked as { bookingId: string }).bookingId);
    await drainOnce();
    await drainOnce();

    const first = (await entries()).find((r) => r.status === "offered")!;
    await declineOffer(first.offerToken!);
    await declineOffer(first.offerToken!);
    await drainOnce();
    await drainOnce();
    await expireOffer(first.id); // deadline firing after the decline

    const rows = await entries();
    expect(rows.filter((r) => r.status === "offered")).toHaveLength(1);
    expect(rows.find((r) => r.id === first.id)!.status).toBe("declined");

    const offers = (await messages()).filter((m) => m.subject.includes("a slot has opened up"));
    expect(offers.map((m) => m.recipient)).toEqual(["+77012222222", "+77013333333"]);
  });

  it("does nothing to an offer that was already claimed", async () => {
    const booked = await book();
    await join("+77012222222");
    await join("+77013333333");
    await cancel((booked as { bookingId: string }).bookingId);
    await drainOnce();
    await drainOnce();

    const offered = (await entries()).find((r) => r.status === "offered")!;
    expect((await acceptOffer(offered.offerToken!)).ok).toBe(true);

    await declineOffer(offered.offerToken!);
    await drainOnce();
    await drainOnce();

    const rows = await entries();
    expect(rows.find((r) => r.id === offered.id)!.status).toBe("booked");
    expect(rows.filter((r) => r.status === "offered")).toHaveLength(0);
    expect(await db.select().from(s.bookings).where(eq(s.bookings.status, "confirmed")))
      .toHaveLength(1);
  });
});

